css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .6); position: relative; }
.loader::before { content: ''; position: absolute; bottom: 3%; left: 20%; width: 60%; height: 4%; border-radius: 999px; background: #cbd5e1; }
.loader::after { content: ''; position: absolute; bottom: 6%; left: 43%; width: 14%; height: 36%; clip-path: polygon(50% 0%, 100% 100%, 0% 100%); background: var(--accent-2); }
.loader .beam { position: absolute; bottom: 42%; left: 4%; width: 92%; height: 7%; border-radius: 999px; background: linear-gradient(90deg, var(--accent), var(--accent-2)); animation: tilt calc(var(--loader-speed) * 2.2) ease-in-out infinite; }
.loader .beam span { position: absolute; bottom: 100%; width: calc(var(--loader-size) * .16); height: calc(var(--loader-size) * .16); border-radius: 50%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 40%, var(--accent-2)), var(--accent)); }
.loader .beam span:nth-child(1) { left: -2%; }
.loader .beam span:nth-child(2) { right: -2%; }
@keyframes tilt { 0%, 100% { transform: rotate(-14deg); } 50% { transform: rotate(14deg); } }
